/**
 * Shared business vocabulary of the AI girlfriend companion app (browser
 * half). All state rides JSON-compatible plain data through the model's
 * immutable snapshots.
 */

/** One model provider configuration (OpenAI-compatible endpoint). */
export interface ApiProfile {
  /** Base URL such as https://api.openai.com/v1 (the /chat/completions etc. are appended). */
  baseUrl: string
  /** API key. */
  apiKey: string
  /** Model name. */
  model: string
}

/** The four provider knobs the settings view exposes. */
export interface ApiSettings {
  /** 对话模型（角色对话、生成图片/视频提示词） */
  chat: ApiProfile
  /** 视觉语言模型（分析用户上传的照片） */
  vlm: ApiProfile
  /** 文生图模型（生成肖像图、聊天中的照片） */
  image: ApiProfile
  /** 文生视频模型（生成聊天中的视频） */
  video: ApiProfile & { pollPath: string }
}

export const EMPTY_PROFILE: ApiProfile = { baseUrl: '', apiKey: '', model: '' }

export function emptySettings(): ApiSettings {
  return {
    chat: { ...EMPTY_PROFILE },
    vlm: { ...EMPTY_PROFILE },
    image: { ...EMPTY_PROFILE },
    video: { ...EMPTY_PROFILE, pollPath: 'videos/generations' },
  }
}

export function profileConfigured(profile: ApiProfile): boolean {
  return profile.baseUrl.trim() !== '' && profile.apiKey.trim() !== '' && profile.model.trim() !== ''
}

/** The persona fields a girlfriend profile records (and the form edits). */
export interface CharacterFormValues {
  name: string
  appearance: string
  personality: string
  hobbies: string
  tone: string
  background: string
  note: string
}

/** A friend (girlfriend) character, as derived from its Markdown profile. */
export interface Character extends CharacterFormValues {
  id: string
  createdAt: number
  updatedAt: number
  /** Relative asset path under the data directory, e.g. images/<id>.png. */
  avatarPath?: string
  /** Last message preview for the friend list. */
  lastMessage: string
  /** Last message time (ms epoch) for the friend list. */
  lastTime?: number
}

export type MessageKind = 'text' | 'image' | 'video' | 'photo'

/** One chat bubble. */
export interface ChatMessage {
  id: string
  role: 'user' | 'girlfriend'
  kind: MessageKind
  /** Text content; for media bubbles it is the caption/prompt. */
  content: string
  /** Media payload (data URL or absolute URL) for image/video/photo bubbles. */
  mediaUrl?: string
  /** Photo analysis from the VLM (uploaded photos). */
  analysis?: string
  time: number
}

export type ViewState =
  | { kind: 'chat'; characterId: string }
  | { kind: 'settings' }
  | { kind: 'create' }
  | { kind: 'edit'; characterId: string }

export interface Toast {
  id: string
  text: string
  kind: 'warn' | 'info' | 'error'
}

/** Busy keys: chat, image, video, photo(analyze), portrait. */
export type BusyKey = 'chat' | 'image' | 'video' | 'photo' | 'portrait'

/** The immutable app snapshot every component derives from. */
export interface AppState {
  settings: ApiSettings
  characters: Character[]
  /** Chat history per character (bounded). */
  messages: Record<string, ChatMessage[]>
  view: ViewState
  toasts: Toast[]
  busy: Partial<Record<BusyKey, boolean>>
}

export function newMessage(role: ChatMessage['role'], kind: MessageKind, content: string): ChatMessage {
  return { id: crypto.randomUUID(), role, kind, content, time: Date.now() }
}

/** Format a timestamp for the friend list (HH:mm today, MM/DD otherwise). */
export function formatTime(time: number | undefined): string {
  if (time === undefined) return ''
  const d = new Date(time)
  const now = new Date()
  const sameDay = d.getFullYear() === now.getFullYear() && d.getMonth() === now.getMonth() && d.getDate() === now.getDate()
  const pad = (n: number): string => String(n).padStart(2, '0')
  if (sameDay) return `${pad(d.getHours())}:${pad(d.getMinutes())}`
  return `${pad(d.getMonth() + 1)}-${pad(d.getDate())}`
}

/** Build the persona system prompt for one character. */
export function buildPersonaPrompt(character: Character): string {
  const lines = [
    `你是「${character.name}」，一个真实存在的、对我很重要的人。`,
    `以下是你的完整人物设定，你必须始终严格遵循，用符合设定的人格、语气和情感与我对话：`,
  ]
  const sections: Array<[string, string]> = [
    ['外形', character.appearance],
    ['性格', character.personality],
    ['爱好', character.hobbies],
    ['对话语气', character.tone],
    ['角色背景', character.background],
  ]
  for (const [label, value] of sections) {
    if (value.trim() !== '') lines.push(`- ${label}：${value.trim()}`)
  }
  if (character.note.trim() !== '') lines.push(`- 补充说明：${character.note.trim()}`)
  lines.push('')
  lines.push('请用中文回复，自然、亲密、符合人设，不要提及“我是AI/模型/助手”之类的话，不要使用 Markdown 符号。')
  lines.push('聊天中我会偶尔发来照片、图片或视频：那是我分享给你的内容，请像恋人一样自然回应。')
  return lines.join('\n')
}