/**
 * The WeChat-like friend list, occupying the layout's `'sidebar'` slot. Shows
 * every girlfriend character with portrait + last message + time; left click
 * opens the chat, right click opens a small character-settings menu. The
 * bottom row carries the settings gear (左下角设置) and the top row the
 * add-friend button. Everything arrives through the shared `useModel` hook.
 */

import { useCallback, useEffect, useRef, useState } from 'react'
import type { Character } from './types.ts'
import { formatTime } from './types.ts'
import { assetUrl } from './host-api.ts'
import type { FriendListComponentProps } from './index.ts'
import css from './FriendList.module.css'

function Avatar(props: { character: Character; size?: number }) {
  const { character } = props
  const size = props.size ?? 44
  if (character.avatarPath !== undefined) {
    return (
      <img
        className={css.avatarImg}
        style={{ width: size, height: size }}
        src={assetUrl(character.avatarPath)}
        alt={character.name}
        draggable={false}
      />
    )
  }
  return (
    <div className={css.avatarFallback} style={{ width: size, height: size, fontSize: size * 0.42 }}>
      {character.name.slice(0, 1)}
    </div>
  )
}

export function FriendList(props: FriendListComponentProps) {
  const { useModel, actions, collapsed } = props
  const characters = useModel(s => s.characters)
  const view = useModel(s => s.view)
  const [menu, setMenu] = useState<{ x: number; y: number; character: Character } | null>(null)
  const [confirmingDelete, setConfirmingDelete] = useState(false)
  const menuRef = useRef<HTMLDivElement | null>(null)

  const closeMenu = useCallback(() => {
    setMenu(null)
    setConfirmingDelete(false)
  }, [])
  useEffect(() => {
    if (menu === null) return
    const onDown = (event: MouseEvent): void => {
      if (menuRef.current === null || !menuRef.current.contains(event.target as Node)) closeMenu()
    }
    window.addEventListener('mousedown', onDown)
    return () => window.removeEventListener('mousedown', onDown)
  }, [menu, closeMenu])

  const onContextMenu = useCallback((event: React.MouseEvent, character: Character) => {
    event.preventDefault()
    setConfirmingDelete(false)
    setMenu({ x: event.clientX, y: event.clientY, character })
  }, [])

  return (
    <div className={css.root} data-collapsed={collapsed || undefined}>
      {collapsed ? (
        <div className={css.rail}>
          <button
            type="button"
            className={css.railButton}
            title="添加好友"
            onClick={() => actions.openCreate()}
          >
            ＋
          </button>
          <button
            type="button"
            className={css.railButton}
            title="设置（对话 / 视觉 / 文生图 / 文生视频 API）"
            onClick={() => actions.openSettings()}
          >
            ⚙
          </button>
        </div>
      ) : (
        <>
          <div className={css.header}>
            <span className={css.title}>我的女友</span>
            <button
              className={css.addButton}
              type="button"
              title="添加好友"
              onClick={() => actions.openCreate()}
            >
              ＋
            </button>
          </div>

          {characters.length === 0 ? (
            <div className={css.empty}>
              <div className={css.emptyEmoji}>💖</div>
              <div className={css.emptyText}>还没有好友</div>
              <button className={css.emptyAction} type="button" onClick={() => actions.openCreate()}>
                点这里添加你的第一位女友
              </button>
            </div>
          ) : (
            <ul className={css.list}>
              {characters.map(character => {
                const active = view.kind === 'chat' && view.characterId === character.id
                return (
                  <li key={character.id}>
                    <button
                      type="button"
                      className={css.item}
                      data-active={active || undefined}
                      onClick={() => actions.openChat(character.id)}
                      onContextMenu={event => onContextMenu(event, character)}
                    >
                      <Avatar character={character} />
                      <span className={css.itemBody}>
                        <span className={css.itemRow}>
                          <span className={css.name}>{character.name}</span>
                          <span className={css.time}>{formatTime(character.lastTime)}</span>
                        </span>
                        <span className={css.preview}>{character.lastMessage}</span>
                      </span>
                    </button>
                  </li>
                )
              })}
            </ul>
          )}

          <div className={css.footer}>
            <button
              type="button"
              className={css.gear}
              title="系统设置（对话 / 视觉 / 文生图 / 文生视频 API）"
              onClick={() => actions.openSettings()}
            >
              <span className={css.gearIcon} aria-hidden>⚙</span>
              <span className={css.gearLabel}>系统设置</span>
            </button>
          </div>
        </>
      )}

      {menu !== null && (
        <div
          ref={menuRef}
          className={css.menu}
          style={{ left: menu.x, top: menu.y }}
        >
          <button
            type="button"
            className={css.menuItem}
            onClick={() => {
              actions.openEdit(menu.character.id)
              closeMenu()
            }}
          >
            编辑人物设定
          </button>
          <button
            type="button"
            className={`${css.menuItem} ${css.menuDanger}`}
            onClick={() => {
              if (!confirmingDelete) {
                setConfirmingDelete(true)
                return
              }
              void actions.deleteCharacter(menu.character.id)
              closeMenu()
            }}
          >
            {confirmingDelete ? '确认删除？再次点击确认' : '删除好友'}
          </button>
        </div>
      )}
    </div>
  )
}