/**
 * The right-hand companion surface, occupying the layout's `'conversation'`
 * slot: the WeChat-like chat dialog, the four-API settings view, and the
 * character create/edit form with portrait generation. All business data and
 * actions come from the shared model through `useModel`/`actions`; local
 * state is limited to ephemeral form/input content.
 */

import { useEffect, useMemo, useRef, useState, type ReactNode } from 'react'
import { assetUrl } from './host-api.ts'
import type { ChatPanelComponentProps } from './index.ts'
import {
  formatTime, profileConfigured,
  type ApiSettings, type Character, type CharacterFormValues, type ChatMessage,
} from './types.ts'
import css from './ChatPanel.module.css'

// ---------------------------------------------------------------- toasts --

function ToastStack(props: ChatPanelComponentProps) {
  const { useModel, actions } = props
  const toasts = useModel(s => s.toasts)
  useEffect(() => {
    const timers = toasts.map(toast => window.setTimeout(() => actions.dismissToast(toast.id), 4200))
    return () => { for (const timer of timers) window.clearTimeout(timer) }
  }, [toasts, actions])
  if (toasts.length === 0) return null
  return (
    <div className={css.toasts}>
      {toasts.map(toast => (
        <button
          key={toast.id}
          type="button"
          className={css.toast}
          data-kind={toast.kind}
          onClick={() => actions.dismissToast(toast.id)}
        >
          {toast.text}
        </button>
      ))}
    </div>
  )
}

// ------------------------------------------------------------- chat view --

function ChatView(props: ChatPanelComponentProps & { character: Character }) {
  const { useModel, actions, character } = props
  const messages = useModel(s => s.messages[character.id] ?? [])
  const busy = useModel(s => s.busy)
  const [draft, setDraft] = useState('')
  const fileRef = useRef<HTMLInputElement | null>(null)
  const scrollRef = useRef<HTMLDivElement | null>(null)

  const tail = useMemo(() => messages.length, [messages])
  useEffect(() => {
    const el = scrollRef.current
    if (el !== null) el.scrollTop = el.scrollHeight
  }, [tail, busy.chat, busy.image, busy.video, busy.photo])

  const send = (): void => {
    if (draft.trim() === '' || busy.chat === true) return
    void actions.sendChat(character.id, draft)
    setDraft('')
  }

  return (
    <div className={css.chatView}>
      <div className={css.chatHeader}>
        <div className={css.chatHeaderAvatar}>
          {character.avatarPath !== undefined
            ? <img src={assetUrl(character.avatarPath)} alt={character.name} />
            : <span>{character.name.slice(0, 1)}</span>}
        </div>
        <div className={css.chatHeaderBody}>
          <div className={css.chatHeaderName}>{character.name}</div>
          <div className={css.chatHeaderStatus}>
            {busy.chat === true ? '正在输入…' : '在线'}
          </div>
        </div>
        <button type="button" className={css.headerEdit} onClick={() => actions.openEdit(character.id)}>
          设定
        </button>
      </div>

      <div className={css.messages} ref={scrollRef}>
        {messages.length === 0 && (
          <div className={css.chatEmpty}>
            <div className={css.chatEmptyEmoji}>💬</div>
            <div>和「{character.name}」打个招呼吧～</div>
          </div>
        )}
        {messages.map(message => (
          <MessageBubble key={message.id} message={message} character={character} />
        ))}
      </div>

      <div className={css.composer}>
        <div className={css.composerInputRow}>
          <textarea
            className={css.composerInput}
            value={draft}
            placeholder={`对「${character.name}」说点什么…（Enter 发送，Shift+Enter 换行）`}
            rows={1}
            onChange={event => setDraft(event.target.value)}
            onKeyDown={event => {
              if (event.key === 'Enter' && !event.shiftKey) {
                event.preventDefault()
                send()
              }
            }}
          />
          <button
            type="button"
            className={css.sendButton}
            disabled={draft.trim() === '' || busy.chat === true}
            onClick={send}
            title="发送"
          >
            {busy.chat === true ? '…' : '➤'}
          </button>
        </div>
        <div className={css.composerTools}>
          <button
            type="button"
            className={css.toolButton}
            disabled={busy.image === true}
            onClick={() => void actions.generateImageMessage(character.id)}
          >
            📷 {busy.image === true ? '正在生成照片…' : '发张照片'}
          </button>
          <button
            type="button"
            className={css.toolButton}
            disabled={busy.video === true}
            onClick={() => void actions.generateVideoMessage(character.id)}
          >
            🎬 {busy.video === true ? '正在生成视频…' : '发个视频'}
          </button>
          <button
            type="button"
            className={css.toolButton}
            disabled={busy.photo === true}
            onClick={() => fileRef.current?.click()}
          >
            ⬆️ {busy.photo === true ? '正在分析照片…' : '上传照片'}
          </button>
          <input
            ref={fileRef}
            type="file"
            accept="image/*"
            hidden
            onChange={event => {
              const file = event.target.files?.[0]
              if (file !== undefined) void actions.uploadPhoto(character.id, file)
              event.target.value = ''
            }}
          />
        </div>
      </div>
    </div>
  )
}

function MessageBubble(props: { message: ChatMessage; character: Character }) {
  const { message, character } = props
  const mine = message.role === 'girlfriend'
  return (
    <div className={css.bubbleRow} data-side={mine ? 'left' : 'right'}>
      {mine && (
        <div className={css.bubbleAvatar}>
          {character.avatarPath !== undefined
            ? <img src={assetUrl(character.avatarPath)} alt={character.name} />
            : <span>{character.name.slice(0, 1)}</span>}
        </div>
      )}
      <div className={css.bubbleColumn}>
        {message.kind === 'image' && message.mediaUrl !== undefined && (
          <div className={css.mediaBubble}>
            <img className={css.mediaImg} src={message.mediaUrl} alt={message.content} />
            {message.content !== '' && <div className={css.mediaCaption}>{message.content}</div>}
          </div>
        )}
        {message.kind === 'video' && message.mediaUrl !== undefined && (
          <div className={css.mediaBubble}>
            <video className={css.mediaVideo} src={message.mediaUrl} controls preload="metadata" />
            {message.content !== '' && <div className={css.mediaCaption}>{message.content}</div>}
          </div>
        )}
        {message.kind === 'photo' && message.mediaUrl !== undefined && (
          <div className={css.mediaBubble}>
            <img className={css.mediaImg} src={message.mediaUrl} alt="照片" />
            {message.analysis !== undefined && (
              <div className={css.photoAnalysis}>🔍 我看到了：{message.analysis}</div>
            )}
          </div>
        )}
        {message.kind === 'text' && message.content !== '' && (
          <div className={css.textBubble}>{message.content}</div>
        )}
        <div className={css.bubbleTime}>{formatTime(message.time)}</div>
      </div>
    </div>
  )
}

// ----------------------------------------------------------- settings --

/** The editable shape shared by every provider card (video adds pollPath). */
interface EditableProfile {
  baseUrl: string
  apiKey: string
  model: string
  pollPath?: string
}

function ProfileEditor(props: {
  title: string
  emoji: string
  profile: EditableProfile
  configured: boolean
  pollPath?: string
  onChange: (next: EditableProfile) => void
  onPollPathChange?: (next: string) => void
}) {
  const { title, emoji, profile, configured, pollPath, onChange, onPollPathChange } = props
  return (
    <div className={css.profileCard} data-configured={configured || undefined}>
      <div className={css.profileHeader}>
        <span className={css.profileEmoji}>{emoji}</span>
        <span className={css.profileTitle}>{title}</span>
        <span className={css.profileStatus}>{configured ? '已配置' : '未配置'}</span>
      </div>
      <label className={css.field}>
        <span className={css.fieldLabel}>模型名</span>
        <input
          className={css.fieldInput}
          value={profile.model}
          placeholder="如 glm-4v-flash / gpt-4o / dall-e-3"
          onChange={event => onChange({ ...profile, model: event.target.value })}
        />
      </label>
      <label className={css.field}>
        <span className={css.fieldLabel}>API 地址</span>
        <input
          className={css.fieldInput}
          value={profile.baseUrl}
          placeholder="https://api.example.com/v1"
          onChange={event => onChange({ ...profile, baseUrl: event.target.value })}
        />
      </label>
      <label className={css.field}>
        <span className={css.fieldLabel}>API Key</span>
        <input
          className={css.fieldInput}
          type="password"
          value={profile.apiKey}
          placeholder="sk-…"
          onChange={event => onChange({ ...profile, apiKey: event.target.value })}
        />
      </label>
      {pollPath !== undefined && onPollPathChange !== undefined && (
        <label className={css.field}>
          <span className={css.fieldLabel}>任务轮询路径(可选)</span>
          <input
            className={css.fieldInput}
            value={pollPath}
            placeholder="videos/generations"
            onChange={event => onPollPathChange(event.target.value)}
          />
        </label>
      )}
    </div>
  )
}

function SettingsView(props: ChatPanelComponentProps) {
  const { useModel, actions } = props
  const saved = useModel(s => s.settings)
  const [form, setForm] = useState<ApiSettings>(() => ({
    chat: { ...saved.chat },
    vlm: { ...saved.vlm },
    image: { ...saved.image },
    video: { ...saved.video },
  }))

  const setChat = (next: EditableProfile): void => {
    setForm(prev => ({ ...prev, chat: { baseUrl: next.baseUrl, apiKey: next.apiKey, model: next.model } }))
  }
  const setVlm = (next: EditableProfile): void => {
    setForm(prev => ({ ...prev, vlm: { baseUrl: next.baseUrl, apiKey: next.apiKey, model: next.model } }))
  }
  const setImage = (next: EditableProfile): void => {
    setForm(prev => ({ ...prev, image: { baseUrl: next.baseUrl, apiKey: next.apiKey, model: next.model } }))
  }
  const setVideo = (next: EditableProfile): void => {
    setForm(prev => ({ ...prev, video: { ...next, pollPath: next.pollPath ?? 'videos/generations' } }))
  }

  return (
    <div className={css.settingsView}>
      <div className={css.settingsHeader}>
        <button type="button" className={css.backButton} onClick={() => actions.goBack()}>
          ‹ 返回
        </button>
        <span className={css.settingsTitle}>设置</span>
        <span />
      </div>
      <div className={css.settingsIntro}>
        以下四组 API 分别用于聊天、照片分析、生成照片/肖像、生成视频。接口需兼容 OpenAI 格式
        （对话与视觉走 <code>/chat/completions</code>，生图走 <code>/images/generations</code>）。
        API Key 仅保存在浏览器本地。
      </div>
      <div className={css.settingsBody}>
        <ProfileEditor
          title="对话模型"
          emoji="💬"
          profile={form.chat}
          configured={profileConfigured(form.chat)}
          onChange={setChat}
        />
        <ProfileEditor
          title="视觉语言模型"
          emoji="👁️"
          profile={form.vlm}
          configured={profileConfigured(form.vlm)}
          onChange={setVlm}
        />
        <ProfileEditor
          title="文生图模型"
          emoji="🎨"
          profile={form.image}
          configured={profileConfigured(form.image)}
          onChange={setImage}
        />
        <ProfileEditor
          title="文生视频模型"
          emoji="🎬"
          profile={form.video}
          configured={profileConfigured(form.video)}
          pollPath={form.video.pollPath}
          onPollPathChange={(pollPath: string) => setForm(prev => ({ ...prev, video: { ...prev.video, pollPath } }))}
          onChange={setVideo}
        />
      </div>
      <div className={css.settingsFooter}>
        <button type="button" className={css.primaryButton} onClick={() => actions.saveSettings(form)}>
          保存设置
        </button>
      </div>
    </div>
  )
}

// ------------------------------------------------- character form --

const EMPTY_FORM: CharacterFormValues = {
  name: '', appearance: '', personality: '', hobbies: '', tone: '', background: '', note: '',
}

function Field(props: {
  label: string
  value: string
  placeholder: string
  rows?: number
  onChange: (value: string) => void
}) {
  const { label, value, placeholder, rows, onChange } = props
  const id = useMemo(() => `gf-${label}`, [label])
  return (
    <div className={css.formField}>
      <label className={css.formLabel} htmlFor={id}>{label}</label>
      {rows === undefined ? (
        <input
          id={id}
          className={css.formInput}
          value={value}
          placeholder={placeholder}
          onChange={event => onChange(event.target.value)}
        />
      ) : (
        <textarea
          id={id}
          className={css.formTextarea}
          value={value}
          placeholder={placeholder}
          rows={rows}
          onChange={event => onChange(event.target.value)}
        />
      )}
    </div>
  )
}

function CharacterFormView(props: ChatPanelComponentProps & { mode: 'create' } | ChatPanelComponentProps & { mode: 'edit'; character: Character }) {
  const { useModel, actions, mode } = props
  const busy = useModel(s => s.busy)
  const character = mode === 'edit' ? props.character : undefined
  const [values, setValues] = useState<CharacterFormValues>(() => (
    character === undefined
      ? { ...EMPTY_FORM }
      : {
        name: character.name, appearance: character.appearance, personality: character.personality,
        hobbies: character.hobbies, tone: character.tone, background: character.background,
        note: character.note,
      }
  ))
  const [portrait, setPortrait] = useState<string>(character?.avatarPath !== undefined
    ? assetUrl(character.avatarPath)
    : '')

  const setValue = (key: keyof CharacterFormValues) => (value: string): void => {
    setValues(prev => ({ ...prev, [key]: value }))
  }

  const generate = async (): Promise<void> => {
    const dataUrl = await actions.generatePortrait(values)
    if (dataUrl !== '') setPortrait(dataUrl)
  }

  const canSave = values.name.trim() !== ''

  return (
    <div className={css.formView}>
      <div className={css.settingsHeader}>
        <button type="button" className={css.backButton} onClick={() => actions.goBack()}>
          ‹ 返回
        </button>
        <span className={css.settingsTitle}>{mode === 'create' ? '添加好友 · 人物设定' : `编辑设定 · ${character?.name ?? ''}`}</span>
        <span />
      </div>

      <div className={css.formBody}>
        <div className={css.portraitPane}>
          <div className={css.portraitBox}>
            {portrait !== ''
              ? <img className={css.portraitImg} src={portrait} alt="肖像预览" />
              : <div className={css.portraitPlaceholder}>👩 生成肖像预览</div>}
          </div>
          <div className={css.portraitActions}>
            <button
              type="button"
              className={css.primaryButton}
              disabled={busy.portrait === true}
              onClick={() => void generate()}
            >
              {busy.portrait === true ? '生成中…' : (portrait !== '' ? '不满意，重新生成' : '生成预览图')}
            </button>
            {portrait !== '' && (
              <div className={css.portraitHint}>满意的话点右下角「{mode === 'create' ? '保存并添加为好友' : '保存修改'}」，肖像会保存为角色相片。</div>
            )}
          </div>
        </div>

        <div className={css.formFields}>
          <Field label="名字" value={values.name} placeholder="例如：小雅" onChange={setValue('name')} />
          <Field
            label="外形参数"
            value={values.appearance}
            placeholder="例如：黑色长发，身高165cm，笑起来有酒窝，喜欢穿浅色连衣裙…"
            rows={2}
            onChange={setValue('appearance')}
          />
          <Field
            label="性格"
            value={values.personality}
            placeholder="例如：温柔体贴、偶尔调皮、粘人但很会照顾人…"
            rows={2}
            onChange={setValue('personality')}
          />
          <Field
            label="爱好"
            value={values.hobbies}
            placeholder="例如：画画、听民谣、做甜点、晚上散步…"
            rows={2}
            onChange={setValue('hobbies')}
          />
          <Field
            label="对话语气"
            value={values.tone}
            placeholder="例如：爱撒娇、称呼我为「亲爱的」，句尾喜欢加「呀」「啦」…"
            rows={2}
            onChange={setValue('tone')}
          />
          <Field
            label="角色背景"
            value={values.background}
            placeholder="例如：我们是大学同学，她毕业后做了插画师，我们刚在一起三个月…"
            rows={3}
            onChange={setValue('background')}
          />
          <Field
            label="补充说明"
            value={values.note}
            placeholder="其它想补充的设定（可选）"
            rows={2}
            onChange={setValue('note')}
          />
        </div>
      </div>

      <div className={css.formFooter}>
        {mode === 'create'
          ? (
            <>
              <button type="button" className={css.ghostButton} onClick={() => void actions.addCharacter(values)}>
                跳过肖像图，直接添加
              </button>
              <button
                type="button"
                className={css.primaryButton}
                disabled={!canSave}
                onClick={() => void actions.addCharacter(values, portrait === '' ? undefined : portrait)}
              >
                满意，保存并添加为好友
              </button>
            </>
          )
          : (
            <>
              <button
                type="button"
                className={css.primaryButton}
                disabled={!canSave}
                onClick={() => void actions.updateCharacter(character!.id, values, portrait === '' ? undefined : portrait)}
              >
                保存修改
              </button>
              {portrait !== '' && <div className={css.portraitHint}>保存修改时会同时更新设定文件并保存当前肖像。</div>}
            </>
          )}
      </div>
    </div>
  )
}

// ------------------------------------------------------------- shell --

export function ChatPanel(props: ChatPanelComponentProps) {
  const { useModel } = props
  const view = useModel(s => s.view)
  const characters = useModel(s => s.characters)

  let body: ReactNode
  if (view.kind === 'settings') {
    body = <SettingsView {...props} />
  } else if (view.kind === 'create') {
    body = <CharacterFormView {...props} mode="create" />
  } else if (view.kind === 'edit') {
    const character = characters.find(c => c.id === view.characterId)
    body = character === undefined
      ? <SettingsView {...props} />
      : <CharacterFormView {...props} mode="edit" character={character} />
  } else {
    const character = characters.find(c => c.id === view.characterId)
    body = character === undefined
      ? (
        <div className={css.hero}>
          <div className={css.heroEmoji}>💘</div>
          <div className={css.heroTitle}>欢迎来到 AI 女友助手</div>
          <div className={css.heroHint}>
            在左侧点击「＋」添加好友，填写你心中的 TA 的外形、性格与故事，
            生成一张满意的肖像，然后就可以开始聊天了。
          </div>
          <button type="button" className={css.primaryButton} onClick={() => props.actions.openCreate()}>
            添加好友
          </button>
        </div>
      )
      : <ChatView {...props} character={character} />
  }

  return (
    <div className={css.root}>
      {body}
      <ToastStack {...props} />
    </div>
  )
}